begin;

-- Help Center: preserve the three existing Getting Started support articles and add two,
-- while seeding five practical articles in every other current category.
with seed(category_slug,title,slug,summary,content,sort_order) as (
values
('getting-started','Create your DRIGHT account safely','getting-started-create-your-dright-account-safely','A quick checklist for creating and securing your DRIGHT account.','<p>A quick checklist for creating and securing your DRIGHT account.</p><h3>What to do</h3><ol><li>Use an email address and phone number you control.</li><li>Complete the requested verification steps and keep recovery details current.</li><li>Use one account per device and do not create extra accounts to refer yourself.</li><li>Review your profile and notification settings before buying, selling, or earning.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',20),
('getting-started','Find your way around DRIGHT','getting-started-find-your-way-around-dright','Learn where Marketplace, Wallet, Referrals, Affiliates, Jobs, Challenges and support tools live.','<p>Learn where Marketplace, Wallet, Referrals, Affiliates, Jobs, Challenges and support tools live.</p><h3>What to do</h3><ol><li>Open the main navigation from the menu icon.</li><li>Use Marketplace to browse products and services and Job Board for opportunities.</li><li>Use Referral, Affiliate and Challenges pages to follow earning activity.</li><li>Open Help or Tutorials whenever you need step-by-step guidance.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',21),
('account','Update your profile and account details','account-update-your-profile-and-account-details','Keep your DRIGHT profile accurate and current.','<p>Keep your DRIGHT profile accurate and current.</p><h3>What to do</h3><ol><li>Open Profile from the navigation menu.</li><li>Review your name, username, contact details and public profile settings.</li><li>Save only accurate information that belongs to you.</li><li>Use Settings for security and notification preferences.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',20),
('account','Sign in and recover access','account-sign-in-and-recover-access','How to sign in safely and recover a forgotten password.','<p>How to sign in safely and recover a forgotten password.</p><h3>What to do</h3><ol><li>Open Sign in and use the email linked to your account.</li><li>Use Forgot password if you cannot remember your password.</li><li>Open the reset link only from a trusted device.</li><li>Contact support if you no longer control the account email.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',21),
('account','One account per device explained','account-one-account-per-device-explained','Why DRIGHT limits account switching and duplicate registrations.','<p>Why DRIGHT limits account switching and duplicate registrations.</p><h3>What to do</h3><ol><li>DRIGHT binds a device installation to an account as an anti-fraud measure.</li><li>Do not create alternate accounts with different emails to obtain referral or affiliate benefits.</li><li>Password recovery is still available for the account already associated with the device.</li><li>Contact support if a legitimate device ownership change causes a problem.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',22),
('account','Manage privacy and public profile visibility','account-manage-privacy-and-public-profile-visibility','Choose what other DRIGHT members can see.','<p>Choose what other DRIGHT members can see.</p><h3>What to do</h3><ol><li>Open Settings or Profile privacy controls.</li><li>Review name, profile, location and social visibility options.</li><li>Keep private information out of public descriptions and posts.</li><li>Recheck privacy settings after adding a new role or store.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',23),
('account','Close or restrict account access','account-close-or-restrict-account-access','What to do if you no longer want to use DRIGHT or suspect unauthorized access.','<p>What to do if you no longer want to use DRIGHT or suspect unauthorized access.</p><h3>What to do</h3><ol><li>Change your password immediately if you suspect unauthorized access.</li><li>Review Security and recent activity.</li><li>Use available account controls or contact support for closure or restriction requests.</li><li>Keep transaction records needed for an active dispute before requesting closure.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',24),
('buying','How to buy an item on DRIGHT','buying-how-to-buy-an-item-on-dright','Complete a marketplace purchase safely.','<p>Complete a marketplace purchase safely.</p><h3>What to do</h3><ol><li>Open the item page and review the description, price and seller information.</li><li>Check delivery terms, digital access details and refund conditions.</li><li>Use the DRIGHT checkout flow and an available payment method.</li><li>Keep the order inside DRIGHT so payment and dispute records are preserved.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',20),
('buying','Check a seller before buying','buying-check-a-seller-before-buying','Use profile, verification and listing information before you pay.','<p>Use profile, verification and listing information before you pay.</p><h3>What to do</h3><ol><li>Review the seller profile and store.</li><li>Read ratings, reviews and item details carefully.</li><li>Be cautious of requests to move payment or conversation off platform.</li><li>Report suspicious listings through DRIGHT.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',21),
('buying','Track an order','buying-track-an-order','Find the current state of a purchase.','<p>Find the current state of a purchase.</p><h3>What to do</h3><ol><li>Open My Orders or Buyer Dashboard.</li><li>Select the order to see its current status.</li><li>Use messages for order-related communication when available.</li><li>Open a support ticket if the order is stuck or materially incorrect.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',22),
('buying','Digital and physical purchases','buying-digital-and-physical-purchases','Understand how delivery differs by item type.','<p>Understand how delivery differs by item type.</p><h3>What to do</h3><ol><li>Digital products may provide access or a file after successful payment.</li><li>Physical items require delivery information and seller fulfillment.</li><li>Services and courses may have their own completion or access rules.</li><li>Read each listing before checkout because fulfillment conditions can differ.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',23),
('buying','Request help with a purchase','buying-request-help-with-a-purchase','What to do when an order has a problem.','<p>What to do when an order has a problem.</p><h3>What to do</h3><ol><li>Collect the order reference and evidence of the issue.</li><li>Contact the seller through DRIGHT where appropriate.</li><li>Use the support or dispute process rather than sending repeated emails to unrelated departments.</li><li>Follow the evidence and response deadlines shown on the case.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',24),
('selling','Become a seller and prepare your store','selling-become-a-seller-and-prepare-your-store','Set up the information buyers need to trust your store.','<p>Set up the information buyers need to trust your store.</p><h3>What to do</h3><ol><li>Complete required account and seller verification.</li><li>Open My Store and add accurate store information.</li><li>Use clear product images, titles and descriptions.</li><li>Publish only items you are authorized to sell.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',20),
('selling','Create a product listing','selling-create-a-product-listing','Post a product that can pass review.','<p>Post a product that can pass review.</p><h3>What to do</h3><ol><li>Choose the correct listing type and category.</li><li>Add truthful title, description, price and fulfillment details.</li><li>Upload clear media that you own or have permission to use.</li><li>Submit for review and respond to any requested changes.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',21),
('selling','Understand listing review statuses','selling-understand-listing-review-statuses','Know what Draft, Pending Review, Approved and other statuses mean.','<p>Know what Draft, Pending Review, Approved and other statuses mean.</p><h3>What to do</h3><ol><li>Draft means the listing is not submitted.</li><li>Pending Review or Under Review means moderators are checking it.</li><li>Returned for Changes or Rejected requires action before publication.</li><li>Approved or Published means the listing can become visible subject to platform controls.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',22),
('selling','Manage sales and fulfillment','selling-manage-sales-and-fulfillment','Handle paid orders professionally.','<p>Handle paid orders professionally.</p><h3>What to do</h3><ol><li>Open Sales to review new paid orders.</li><li>Follow the item-specific processing and delivery requirements.</li><li>Do not mark an order delivered before fulfillment is complete.</li><li>Keep proof of delivery or completion when relevant.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',23),
('selling','Seller rules and prohibited behavior','selling-seller-rules-and-prohibited-behavior','Protect buyers and your seller standing.','<p>Protect buyers and your seller standing.</p><h3>What to do</h3><ol><li>Do not misrepresent products, prices, stock or delivery.</li><li>Do not use fake reviews, self-purchases or referral loops.</li><li>Do not sell illegal, stolen, counterfeit or restricted content.</li><li>Repeated or serious violations can result in listing removal, restriction or suspension.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',24),
('payments','How DRIGHT checkout works','payments-how-dright-checkout-works','Understand the payment flow before completing a purchase.','<p>Understand the payment flow before completing a purchase.</p><h3>What to do</h3><ol><li>Confirm the item and amount before starting payment.</li><li>Use only the payment methods displayed by DRIGHT at checkout.</li><li>Wait for the verification screen or callback before retrying.</li><li>Keep the payment reference if you need support.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',20),
('payments','A payment succeeded but DRIGHT has not updated','payments-a-payment-succeeded-but-dright-has-not-updated','Steps to take when the gateway and DRIGHT status differ.','<p>Steps to take when the gateway and DRIGHT status differ.</p><h3>What to do</h3><ol><li>Do not repeatedly pay for the same order.</li><li>Wait briefly for payment verification to complete.</li><li>Check the order or transaction history for an updated status.</li><li>Contact Payment Support with the reference if the status remains wrong.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',21),
('payments','Avoid payment scams','payments-avoid-payment-scams','Recognize risky payment requests.','<p>Recognize risky payment requests.</p><h3>What to do</h3><ol><li>Never send money to an account supplied in an unsolicited message unless DRIGHT explicitly shows it as part of checkout.</li><li>Do not share OTPs, passwords or recovery codes.</li><li>Confirm the domain is DRIGHT before entering credentials.</li><li>Report suspected payment fraud immediately.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',22),
('payments','Payment currency and amount','payments-payment-currency-and-amount','Why the amount shown at checkout is authoritative.','<p>Why the amount shown at checkout is authoritative.</p><h3>What to do</h3><ol><li>Review the checkout currency and total before paying.</li><li>Gateway or bank conversion fees may differ from the DRIGHT item price.</li><li>Do not alter payment references or amounts.</li><li>If you see an unexpected amount, stop and contact support before paying.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',23),
('payments','Payment records and receipts','payments-payment-records-and-receipts','Where to find evidence of a completed transaction.','<p>Where to find evidence of a completed transaction.</p><h3>What to do</h3><ol><li>Open Wallet, Transactions or the relevant order.</li><li>Record the DRIGHT reference and gateway reference when available.</li><li>Use these references for disputes or support.</li><li>Do not post full payment credentials publicly.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',24),
('wallet','Understand your wallet balances','wallet-understand-your-wallet-balances','Learn the difference between balance, pending and available funds.','<p>Learn the difference between balance, pending and available funds.</p><h3>What to do</h3><ol><li>Open Wallet to view your current balances.</li><li>Pending funds may still be waiting for settlement or eligibility conditions.</li><li>Available funds are the amount currently eligible for supported actions.</li><li>Review Transaction History for the source of each movement.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',20),
('wallet','Fund your wallet','wallet-fund-your-wallet','Add funds using an available DRIGHT method.','<p>Add funds using an available DRIGHT method.</p><h3>What to do</h3><ol><li>Open Wallet and choose Fund Wallet.</li><li>Select one of the payment methods currently offered.</li><li>Confirm the amount before continuing to the provider.</li><li>Return to DRIGHT and verify the transaction status.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',21),
('wallet','Read your transaction history','wallet-read-your-transaction-history','Use the wallet ledger to understand credits and debits.','<p>Use the wallet ledger to understand credits and debits.</p><h3>What to do</h3><ol><li>Open Transaction History.</li><li>Filter or review recent entries.</li><li>Match references to orders, commissions, refunds or withdrawals.</li><li>Report an entry you do not recognize.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',22),
('wallet','Affiliate and referral earnings in your wallet','wallet-affiliate-and-referral-earnings-in-your-wallet','Understand how eligible earnings reach your balances.','<p>Understand how eligible earnings reach your balances.</p><h3>What to do</h3><ol><li>Earnings appear only after the qualifying activity is verified.</li><li>Reversed, refunded or fraudulent transactions may reverse related rewards.</li><li>Pending commissions can differ from available funds.</li><li>Use the relevant Affiliate or Referral dashboard for source details.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',23),
('wallet','Protect your wallet','wallet-protect-your-wallet','Security practices for wallet access.','<p>Security practices for wallet access.</p><h3>What to do</h3><ol><li>Use a strong password and secure recovery methods.</li><li>Never share OTPs or wallet verification codes.</li><li>Avoid VPN/proxy use where prohibited because it can trigger fraud review.</li><li>Report unauthorized activity immediately.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',24),
('withdrawals','Add and verify a payout account','withdrawals-add-and-verify-a-payout-account','Prepare an account for withdrawals.','<p>Prepare an account for withdrawals.</p><h3>What to do</h3><ol><li>Open Withdraw or payout settings.</li><li>Enter the payout details exactly as required.</li><li>Complete available account-name or ownership verification.</li><li>Review the verified name before submitting a withdrawal.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',20),
('withdrawals','Submit a withdrawal','withdrawals-submit-a-withdrawal','Move eligible funds using a supported payout method.','<p>Move eligible funds using a supported payout method.</p><h3>What to do</h3><ol><li>Confirm your available balance meets the minimum and any requirements.</li><li>Choose a verified payout account or method.</li><li>Review the amount and fees if shown.</li><li>Submit once and track the status rather than creating duplicates.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',21),
('withdrawals','Withdrawal statuses explained','withdrawals-withdrawal-statuses-explained','Understand pending, processing, paid and failed states.','<p>Understand pending, processing, paid and failed states.</p><h3>What to do</h3><ol><li>Pending means the request has been received.</li><li>Processing means automated or manual payout work is underway.</li><li>Paid means DRIGHT recorded completion of the payout process.</li><li>Failed, rejected or returned states require reviewing the reason before retrying.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',22),
('withdrawals','Withdrawal verification and fraud checks','withdrawals-withdrawal-verification-and-fraud-checks','Why some withdrawals need additional review.','<p>Why some withdrawals need additional review.</p><h3>What to do</h3><ol><li>DRIGHT may check identity, account ownership, referral integrity and transaction history.</li><li>Unusual device or network signals can trigger review.</li><li>Provide only genuine requested evidence.</li><li>Do not attempt to bypass review with another account or device.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',23),
('withdrawals','A withdrawal has not arrived','withdrawals-a-withdrawal-has-not-arrived','What to check before contacting support.','<p>What to check before contacting support.</p><h3>What to do</h3><ol><li>Confirm the withdrawal status and destination details.</li><li>Allow any stated processing window to pass.</li><li>Check your receiving institution for the reference if available.</li><li>Send one support ticket with the withdrawal ID and supporting details.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',24),
('affiliates','Start affiliate marketing on DRIGHT','affiliates-start-affiliate-marketing-on-dright','Learn the basic affiliate workflow.','<p>Learn the basic affiliate workflow.</p><h3>What to do</h3><ol><li>Open the Affiliate area or an affiliate-enabled item.</li><li>Review the commission and conditions before sharing.</li><li>Copy your unique affiliate link.</li><li>Share responsibly and monitor verified conversions.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',20),
('affiliates','DRIGHT Starter affiliate requirement','affiliates-dright-starter-affiliate-requirement','Understand the Starter sales requirement for newly eligible affiliates.','<p>Understand the Starter sales requirement for newly eligible affiliates.</p><h3>What to do</h3><ol><li>Open DRIGHT Starter to see your live verified-sales progress.</li><li>The required target is controlled by DRIGHT and can change; the page always shows the current requirement.</li><li>Only verified qualifying Starter sales count toward the unlock requirement.</li><li>After completion, eligible affiliate products become available according to current platform rules.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',21),
('affiliates','Copy and share an affiliate link','affiliates-copy-and-share-an-affiliate-link','Make sure referrals are attributed correctly.','<p>Make sure referrals are attributed correctly.</p><h3>What to do</h3><ol><li>Use the Copy affiliate link action on the item or affiliate dashboard.</li><li>Do not edit the tracking portion of the link.</li><li>Avoid deceptive spam or unsolicited mass messaging.</li><li>Check your affiliate dashboard for attributed verified sales.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',22),
('affiliates','Affiliate commissions explained','affiliates-affiliate-commissions-explained','How commissions are calculated and validated.','<p>How commissions are calculated and validated.</p><h3>What to do</h3><ol><li>The item or campaign shows the applicable commission rate.</li><li>Commission normally requires an eligible attributed sale.</li><li>Refunds, chargebacks, duplicate/self-referrals or fraud can reverse a commission.</li><li>Wallet availability can occur after validation or settlement.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',23),
('affiliates','Affiliate leaderboard and challenges','affiliates-affiliate-leaderboard-and-challenges','Use leaderboards to understand challenge progress.','<p>Use leaderboards to understand challenge progress.</p><h3>What to do</h3><ol><li>Open Challenges and choose the Affiliate section.</li><li>Select the relevant affiliate leaderboard.</li><li>Use the action button to open the product or affiliate area linked to that challenge.</li><li>Leaderboard rewards remain subject to eligibility and anti-fraud checks.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',24),
('referrals','Find and copy your referral link','referrals-find-and-copy-your-referral-link','Share the correct DRIGHT referral link.','<p>Share the correct DRIGHT referral link.</p><h3>What to do</h3><ol><li>Open Refer from the navigation menu.</li><li>Copy the unique link shown for your account.</li><li>Share it with genuine new users who choose to join DRIGHT.</li><li>Do not create or control the referred account yourself.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',20),
('referrals','What counts as a verified referral','referrals-what-counts-as-a-verified-referral','Understand why raw link clicks are not the same as qualifying referrals.','<p>Understand why raw link clicks are not the same as qualifying referrals.</p><h3>What to do</h3><ol><li>A referral must be attributable to your referral link or code.</li><li>The referred account must be genuine and satisfy the current qualifying action.</li><li>Duplicate, self-controlled or fraudulent accounts do not qualify.</li><li>DRIGHT may reverse rewards linked to refunded or fraudulent activity.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',21),
('referrals','Buyer referral challenges','referrals-buyer-referral-challenges','How referred buyers can affect leaderboard progress.','<p>How referred buyers can affect leaderboard progress.</p><h3>What to do</h3><ol><li>Open Challenges and choose Referral.</li><li>Select the buyer-referrer leaderboard.</li><li>The leaderboard counts the qualifying activity described on the challenge.</li><li>Use the referral page to share your link and track progress.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',22),
('referrals','Multi-level referral rewards','referrals-multi-level-referral-rewards','Understand direct and downstream referral levels.','<p>Understand direct and downstream referral levels.</p><h3>What to do</h3><ol><li>Direct referrals are linked to you at the first level.</li><li>Additional supported levels can receive different percentages under current program settings.</li><li>Rewards are subject to qualifying actions, limits and anti-fraud rules.</li><li>Check current DRIGHT program information before relying on a specific reward amount.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',23),
('referrals','Referral fraud rules','referrals-referral-fraud-rules','Actions that can cause referrals to be rejected.','<p>Actions that can cause referrals to be rejected.</p><h3>What to do</h3><ol><li>Do not refer yourself through another email, role, browser or device.</li><li>Do not buy, rent or automate fake accounts.</li><li>Do not use VPNs, proxies or location masking to evade anti-fraud controls.</li><li>DRIGHT may flag, reverse rewards, restrict or suspend accounts after review.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',24),
('promotions','Promote a listing on DRIGHT','promotions-promote-a-listing-on-dright','Use available promotion tools to increase legitimate visibility.','<p>Use available promotion tools to increase legitimate visibility.</p><h3>What to do</h3><ol><li>Open Promote or the relevant listing action.</li><li>Choose an available promotion placement or package.</li><li>Review duration, targeting and price.</li><li>Submit the promotion and follow its approval/status.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',20),
('promotions','Marketplace flyers and sponsored placements','promotions-marketplace-flyers-and-sponsored-placements','How banner and flyer advertising works.','<p>How banner and flyer advertising works.</p><h3>What to do</h3><ol><li>Approved DRIGHT and sponsored flyers can appear in rotating promotional surfaces.</li><li>Sponsored content is labelled when it is paid advertising.</li><li>Clicking a flyer opens its configured DRIGHT or external destination.</li><li>Admins can pause or remove a flyer if it violates policy.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',21),
('promotions','Create advertising materials','promotions-create-advertising-materials','Prepare assets that fit DRIGHT promotional surfaces.','<p>Prepare assets that fit DRIGHT promotional surfaces.</p><h3>What to do</h3><ol><li>Use clear, truthful copy and readable media.</li><li>Do not imitate DRIGHT verification badges or make false earnings guarantees.</li><li>Link directly to the relevant product, store or campaign.</li><li>Keep source files you are authorized to use.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',22),
('promotions','Promotion analytics','promotions-promotion-analytics','Understand impressions, clicks and conversions.','<p>Understand impressions, clicks and conversions.</p><h3>What to do</h3><ol><li>Impressions measure eligible displays of the promotion.</li><li>Clicks record interaction with the promotion.</li><li>Conversions depend on the supported campaign event and attribution.</li><li>Use trends rather than a single metric to evaluate performance.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',23),
('promotions','Advertising policy basics','promotions-advertising-policy-basics','Key rules for promoted content.','<p>Key rules for promoted content.</p><h3>What to do</h3><ol><li>Ads must be legal, truthful and appropriate for the destination.</li><li>Do not use malware, phishing, misleading redirects or impersonation.</li><li>Claims about price, earnings or availability must match the destination.</li><li>DRIGHT may reject, pause or remove non-compliant campaigns.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',24),
('security','Protect your DRIGHT account','security-protect-your-dright-account','Core security practices every user should follow.','<p>Core security practices every user should follow.</p><h3>What to do</h3><ol><li>Use a unique strong password.</li><li>Keep email, phone and recovery access secure.</li><li>Do not share OTPs, passwords, private keys or recovery codes.</li><li>Review Security and report unfamiliar activity.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',20),
('security','VPN, proxy and Tor policy','security-vpn-proxy-and-tor-policy','Why DRIGHT can flag anonymized network access.','<p>Why DRIGHT can flag anonymized network access.</p><h3>What to do</h3><ol><li>DRIGHT prohibits using VPNs, anonymizing proxies or Tor to disguise identity, location or device relationships for platform use.</li><li>Network intelligence can produce false positives, so a signal is treated as a risk indicator rather than automatic proof.</li><li>A flagged account can be asked for additional verification and confirmed abuse may lead to restriction or suspension.</li><li>If you believe a signal is wrong, contact support and provide the requested verification.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',21),
('security','Device and account protection','security-device-and-account-protection','How device-level anti-fraud controls work.','<p>How device-level anti-fraud controls work.</p><h3>What to do</h3><ol><li>DRIGHT may associate an app/browser installation with an account to prevent duplicate-account abuse.</li><li>Creating multiple accounts on one device to obtain referral, trial or affiliate benefits is prohibited.</li><li>Password recovery remains available for the legitimate bound account.</li><li>Contact support for legitimate device-transfer or shared-device problems.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',22),
('security','Recognize phishing and impersonation','security-recognize-phishing-and-impersonation','How to avoid fake DRIGHT support messages.','<p>How to avoid fake DRIGHT support messages.</p><h3>What to do</h3><ol><li>Check the site and sender before entering credentials.</li><li>DRIGHT support should never need your password or OTP.</li><li>Do not install unknown software sent in a support message.</li><li>Report suspicious messages through the Help Center.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',23),
('security','What happens after a security flag','security-what-happens-after-a-security-flag','Understand the review process.','<p>Understand the review process.</p><h3>What to do</h3><ol><li>A risk signal may add an internal security flag.</li><li>Some actions may require verification or manual review.</li><li>DRIGHT can restrict activity while investigating material fraud risk.</li><li>Users can provide evidence or appeal an incorrect determination through support.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',24),
('verification','Why verification is required','verification-why-verification-is-required','Understand when DRIGHT asks for identity or business information.','<p>Understand when DRIGHT asks for identity or business information.</p><h3>What to do</h3><ol><li>Verification helps protect users, payments and marketplace integrity.</li><li>Different roles or actions can require different checks.</li><li>Provide only genuine, current documents that belong to you.</li><li>Verification status can affect listing, payout or other protected actions.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',20),
('verification','Submit readable identity documents','verification-submit-readable-identity-documents','Improve the chance of a smooth verification review.','<p>Improve the chance of a smooth verification review.</p><h3>What to do</h3><ol><li>Use an accepted document type shown in the form.</li><li>Capture the full document clearly without blur or glare.</li><li>Ensure required information is visible and current.</li><li>Submit through DRIGHT''s secure upload flow rather than public messages.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',21),
('verification','Selfie and identity consistency','verification-selfie-and-identity-consistency','Why identity information must match.','<p>Why identity information must match.</p><h3>What to do</h3><ol><li>Use your own identity and current likeness.</li><li>Names and key identity details should be consistent across required documents.</li><li>Do not edit or digitally alter verification evidence.</li><li>Mismatches can require resubmission or manual review.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',22),
('verification','Verification statuses explained','verification-verification-statuses-explained','Understand pending, approved and resubmission states.','<p>Understand pending, approved and resubmission states.</p><h3>What to do</h3><ol><li>Pending or under review means a decision has not been completed.</li><li>Approved or verified means the specific check passed.</li><li>Needs resubmission means the evidence must be replaced or corrected.</li><li>Rejected or suspected-fraud states may require support or appeal steps.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',23),
('verification','Keep verification data secure','verification-keep-verification-data-secure','How DRIGHT treats verification materials.','<p>How DRIGHT treats verification materials.</p><h3>What to do</h3><ol><li>Verification documents should be stored in protected systems rather than public profiles.</li><li>Access is limited to authorized review workflows.</li><li>DRIGHT may retain required compliance and audit records according to policy and law.</li><li>Read the Privacy Policy for categories of data, purposes and rights.</li></ol><h3>Good practice</h3><p>Use only the current controls and payment methods shown inside DRIGHT. Keep important references, do not share passwords or OTPs, and contact the relevant support channel if a protected action cannot be completed.</p>',24)
)
insert into public.help_articles(category_id,title,slug,summary,content,tags,sort_order,status,is_published,publish_at,is_deleted)
select c.id,s.title,s.slug,s.summary,s.content,array[c.slug,'dright','help']::text[],s.sort_order,'published',true,now(),false
from seed s join public.help_categories c on c.slug=s.category_slug
on conflict(slug) do update set
  category_id=excluded.category_id,title=excluded.title,summary=excluded.summary,content=excluded.content,
  sort_order=excluded.sort_order,status='published',is_published=true,is_deleted=false,updated_at=now();

