insert into public.tutorials(category_id,title,slug,description,content,video_type,video_url,duration_minutes,difficulty,tags,sort_order,status,is_published,publish_at,is_deleted)
select c.id,s.title,s.slug,s.description,s.content,'direct',null,s.duration_minutes,s.difficulty,array[c.slug,'dright','guide']::text[],s.sort_order,'published',true,now(),false
from seed s join public.tutorial_categories c on c.slug=s.category_slug
on conflict(slug) do update set
  category_id=excluded.category_id,title=excluded.title,description=excluded.description,content=excluded.content,
  duration_minutes=excluded.duration_minutes,difficulty=excluded.difficulty,sort_order=excluded.sort_order,
  status='published',is_published=true,is_deleted=false,updated_at=now();

-- Publish comprehensive legal pages and keep stable URLs for existing Terms/Privacy links.
update public.legal_pages
set title='DRIGHT Terms and Conditions',content='<h1>DRIGHT Terms and Conditions</h1>
<p><strong>Effective date:</strong> 25 September 2026. These Terms and Conditions govern access to and use of DRIGHT, including the marketplace, stores, products, services, courses, jobs, tasks, communities, messages, referrals, affiliate programs, challenges, wallets, subscriptions, promotions and other features made available through the platform.</p>
<h2>1. Eligibility and acceptance</h2><p>You must be at least 18 years old and legally able to enter into these Terms. By creating an account, purchasing, listing, posting, promoting, referring, affiliating, receiving rewards, or otherwise using DRIGHT, you agree to these Terms and the policies that apply to the relevant feature.</p>
<h2>2. Accounts and device integrity</h2><p>Provide accurate information and keep your credentials secure. DRIGHT may restrict one account to a device or browser installation to reduce duplicate accounts, self-referrals, trial abuse, payment fraud and related misconduct. You must not create, control or coordinate additional accounts to obtain referral, affiliate, challenge, subscription, promotional or other benefits. Account sharing, credential resale and identity impersonation are prohibited.</p>
<h2>3. VPN, proxy, Tor and location masking</h2><p>Use of VPNs, anonymizing proxies, Tor, traffic relays or similar services to conceal or manipulate identity, location, device relationships, referral attribution, eligibility, payments, verification or other platform controls is prohibited. DRIGHT may use IP/network intelligence as a fraud signal. Because network intelligence can produce false positives, a signal is not treated as conclusive proof by itself. DRIGHT may request additional verification, temporarily restrict sensitive actions, flag the account for review, reverse ineligible rewards, or suspend an account when abuse is confirmed or when material risk remains unresolved. Users may contact support to challenge an incorrect flag.</p>
<h2>4. Marketplace conduct</h2><p>Listings and offers must be truthful, lawful and within DRIGHT rules. Sellers are responsible for rights to their products, services, media and descriptions; accurate pricing; fulfillment; and required disclosures. Prohibited conduct includes counterfeit or stolen goods, deceptive descriptions, fabricated reviews, manipulation of ratings, malware, phishing, illegal content, unauthorized intellectual property, and attempts to move protected transactions off-platform to evade DRIGHT controls.</p>
<h2>5. Listing review and moderation</h2><p>Listings may move through Draft, Pending Review, Under Review, Approved, Rejected, Returned for Changes, Published, Hidden or Archived states. Review approval does not guarantee future availability. DRIGHT may re-review, limit or remove content when rules, risk, legal requirements or platform safety require it.</p>
<h2>6. Buying, orders and disputes</h2><p>Buyers must review item descriptions, delivery conditions and seller information before paying. Order states can include Pending, Paid, Processing, Delivered, Completed, Cancelled, Refunded or Disputed. Keep communications and payment references on DRIGHT where possible. Refund and dispute outcomes depend on the transaction, evidence, applicable policy and law.</p>
<h2>7. Payments, wallet and withdrawals</h2><p>Payment methods are those currently shown by DRIGHT. Users must not manipulate payment references, chargebacks, settlement records or payout accounts. Wallet figures may include pending, available, commission, refund or other balances with different eligibility rules. Withdrawals can require identity, account-ownership and anti-fraud review. A displayed balance is not a guarantee that every amount is immediately withdrawable.</p>
<h2>8. Subscriptions and trials</h2><p>Certain professional features may require an active subscription after a trial. Trial length, price, currency, grace periods and required roles are the values shown in the account at the time. Attempts to reset or multiply trials through extra accounts, devices, identities or network masking are prohibited. DRIGHT may change future plan features or prices with appropriate notice; changes do not retroactively rewrite a completed payment.</p>
<h2>9. DRIGHT Starter and affiliate access</h2><p>The DRIGHT Starter product can provide Starter access, affiliate commission and/or an extended trial according to the current product settings. Some new affiliate accounts may be required to complete a configurable number of verified DRIGHT Starter sales before other affiliate products are unlocked. The current target and your verified progress are displayed on the Starter page. Only genuine, attributed, verified sales count. Refunds, reversals, self-purchases, duplicate accounts, coordinated accounts and fraudulent activity can be excluded or reversed.</p>
<h2>10. Affiliate program</h2><p>Affiliate rates are determined by the relevant item or program and can differ by seller. Attribution must result from a genuine affiliate relationship. You must not use misleading claims, forced clicks, spam, cookie stuffing, impersonation, hidden redirects or self-dealing. Commissions can remain pending until qualification and can be reversed for refunds, chargebacks, fraud or attribution errors.</p>
<h2>11. Referral program</h2><p>Referral rewards are subject to the current program configuration, qualifying actions, limits and anti-fraud checks. You may share your referral link with genuine prospective users. You may not refer yourself, create accounts for referred users, purchase or automate accounts, misrepresent rewards, or use devices, identities, emails, phone numbers, payment methods or network masking to manufacture referrals.</p>
<h2>12. Challenges and leaderboards</h2><p>Challenge rules, periods, reward amounts and qualifying metrics are shown on the relevant challenge. Leaderboard positions may change as qualifying activity is verified. Rewards can require eligibility review and can be withheld or reversed where fraud, duplicate activity, refunds, chargebacks or rule violations affect qualification. Gamified or benchmark competition elements, where used, do not create a right to payment unless the published challenge expressly makes the participant eligible for a prize.</p>
<h2>13. Jobs, tasks, services and courses</h2><p>Users posting jobs, tasks, services or courses must describe them accurately and comply with applicable law. DRIGHT does not authorize discrimination, scams, illegal work, false credentials or deceptive earnings claims. Users are responsible for evaluating opportunities and meeting any contractual or legal obligations that arise from their own agreements.</p>
<h2>14. Communities, posts and messaging</h2><p>Do not harass, threaten, impersonate, expose private information, distribute malware, coordinate fraud, post illegal content, or use DRIGHT for unsolicited bulk spam. Community owners and moderators must apply platform rules. DRIGHT may moderate, remove or restrict content and accounts when necessary for safety or compliance.</p>
<h2>15. Advertising and promotions</h2><p>Paid promotions, sponsored flyers and advertisements must be truthful and must comply with DRIGHT advertising rules. Sponsored content may be labelled. Advertisers must not use fake scarcity, false earnings guarantees, deceptive redirects, intellectual-property infringement, malware or prohibited products. DRIGHT may reject, pause or remove campaigns.</p>
<h2>16. Verification and KYC</h2><p>DRIGHT may require identity, address, selfie, phone, email, business or other verification before protected actions. Submitted evidence must be authentic and belong to the submitting person or authorized entity. Forged, altered or borrowed documents can result in rejection, restriction or suspension.</p>
<h2>17. Security and fraud monitoring</h2><p>To protect users and DRIGHT, security systems may evaluate account identifiers, email and phone verification, device/account binding, IP address, approximate IP-derived location, network characteristics, payment and payout references, referral relationships, account activity, verification status and fraud patterns. Precise device location is used only where the user grants the relevant permission or another lawful basis applies. Security data is handled under the Privacy Policy.</p>
<h2>18. Enforcement</h2><p>Depending on severity and evidence, DRIGHT may warn, request verification, remove content, pause payouts, reverse ineligible rewards, limit features, suspend or terminate accounts, and preserve records required for disputes, fraud prevention or legal compliance. Where appropriate, users may appeal through the support process.</p>
<h2>19. Intellectual property</h2><p>DRIGHT names, software, interface elements and platform content are protected by applicable rights. Users retain rights in content they lawfully own but grant DRIGHT the permissions reasonably necessary to host, display, distribute and moderate that content for platform operation.</p>
<h2>20. Availability and changes</h2><p>Features can be added, changed, hidden, disabled, scheduled, restricted or discontinued. DRIGHT does not guarantee uninterrupted availability. Material legal-policy changes can be versioned and published through the legal center.</p>
<h2>21. Limitation and responsibility</h2><p>To the extent permitted by applicable law, DRIGHT is not responsible for losses caused by user fraud, off-platform transactions, unauthorized credential sharing, third-party outages, or user violations. Nothing in these Terms excludes rights that cannot legally be excluded.</p>
<h2>22. Contact and notices</h2><p>Use the Help Center and the support channels currently displayed by DRIGHT. A support address can be hidden when it is inactive, so users should rely on the channels shown in the product rather than an old saved address.</p>
<p><em>This document is a product policy draft and should be reviewed by qualified counsel for the jurisdictions in which DRIGHT operates.</em></p>',is_published=true,publish_at=coalesce(publish_at,now()),version_number=greatest(version_number,2),updated_at=now()
where slug='terms-of-service';

update public.legal_pages
set content='<h1>DRIGHT Privacy Policy</h1>
<p><strong>Effective date:</strong> 25 September 2026. This Privacy Policy explains the categories of information DRIGHT can process to operate the marketplace, payments, accounts, security, referrals, affiliate features, subscriptions, communities, jobs, challenges and support.</p>
<h2>Information you provide</h2><p>This can include name, username, email, phone, date of birth or age confirmation, profile information, store/listing content, messages, support submissions, payment references, payout details, verification documents and information you choose to publish.</p>
<h2>Account, device and security information</h2><p>DRIGHT can process account identifiers, device/browser installation identifiers used for one-account-per-device controls, login and security events, IP address, user-agent/device category, approximate IP-derived country/region/city, network-risk indicators, referral relationships and other anti-fraud signals. These signals help identify duplicate accounts, self-referrals, payment abuse and attempts to evade platform rules.</p>
<h2>Location information</h2><p>Approximate location can be derived from an IP address for security, localization or fraud prevention. Precise GPS/location permission is separate and is accessed only when the user grants the relevant permission or another lawful basis applies. IP-derived location can be inaccurate and is not treated as precise physical location.</p>
<h2>VPN and network intelligence</h2><p>DRIGHT may use a network-intelligence provider to identify signals such as VPN, proxy, Tor, hosting/datacenter or abuse indicators. These results can be incomplete or wrong, so they are used as risk signals and may be reviewed together with other account evidence.</p>
<h2>Transactions and commerce</h2><p>DRIGHT processes order, wallet, commission, referral, subscription, refund, dispute and withdrawal records necessary to provide services, maintain accounting records, detect fraud and resolve support cases. Payment providers may process payment credentials under their own privacy terms.</p>
<h2>How information is used</h2><ul><li>Provide and personalize DRIGHT features.</li><li>Authenticate accounts and recover access.</li><li>Process orders, subscriptions, commissions and withdrawals.</li><li>Verify identities and protected roles.</li><li>Prevent fraud, duplicate accounts, self-referrals and security abuse.</li><li>Moderate content and enforce platform rules.</li><li>Provide customer support and maintain audit trails.</li><li>Measure product performance where permitted by consent and law.</li></ul>
<h2>Cookies and local storage</h2><p>DRIGHT uses essential browser storage for authentication, security, language/theme preferences and core product operation. Optional analytics or marketing storage is controlled by the cookie preference where implemented. See the Cookie Policy for more detail.</p>
<h2>Sharing and processors</h2><p>Information can be shared with service providers that support hosting, authentication, payments, email, storage, security, fraud prevention, analytics and customer support, only as needed for the service and subject to applicable obligations. DRIGHT does not authorize advertisers to receive private conversation content simply because an advertisement is displayed.</p>
<h2>Retention</h2><p>Records are kept for as long as reasonably necessary for account operation, legal obligations, payments, disputes, security, fraud prevention and audit requirements. Retention periods can differ by data category.</p>
<h2>Your choices and rights</h2><p>Depending on applicable law, you may have rights to access, correct, delete, restrict or object to certain processing, or request a copy of information. Some records may need to be retained for legal, security, fraud-prevention or transaction-integrity reasons. Privacy and account requests should be made through the current Help Center channels.</p>
<h2>Security</h2><p>DRIGHT uses technical and organizational controls such as authentication, row-level access controls, private storage for sensitive documents, audit logs and anti-fraud monitoring. No system can guarantee absolute security.</p>
<h2>Policy changes</h2><p>Material updates can be published as a new version in the DRIGHT Legal Center.</p>
<p><em>This policy is a product-policy draft and should be reviewed by qualified privacy counsel before relying on it as jurisdiction-specific legal advice.</em></p>',is_published=true,publish_at=coalesce(publish_at,now()),version_number=greatest(version_number,2),updated_at=now()
where slug='privacy-policy';

insert into public.legal_pages(title,slug,page_type,content,is_published,publish_at,version_number,is_deleted)
values('Cookie Policy','cookie-policy','cookie','<h1>DRIGHT Cookie Policy</h1>
<p><strong>Effective date:</strong> 25 September 2026. This policy explains how DRIGHT uses cookies, browser storage and similar technologies on the web experience.</p>
<h2>Necessary storage</h2><p>Necessary cookies or storage can be used for sign-in state, session security, fraud prevention, account/device protection, load balancing, language, theme, consent choices and other functionality required to provide DRIGHT. Choosing “Necessary only” does not disable storage that is required for security or core service operation.</p>
<h2>Preference storage</h2><p>DRIGHT can remember interface choices such as language, theme, dismissed notices and other user preferences so they do not need to be selected repeatedly.</p>
<h2>Analytics</h2><p>Where enabled and permitted, analytics technologies can help DRIGHT understand feature usage, performance and errors. The cookie consent control records whether optional analytics are allowed.</p>
<h2>Marketing and advertising</h2><p>Where enabled and permitted, marketing technologies can measure promotional engagement or campaign performance. Paid DRIGHT promotional surfaces remain labelled as sponsored when applicable. Choosing Necessary only disables optional marketing storage controlled by DRIGHT''s consent layer; third-party destinations can have their own policies.</p>
<h2>Security and anti-fraud</h2><p>Security processing such as session validation, account-device binding, IP/network risk evaluation and abuse prevention is treated as essential platform security rather than optional advertising analytics.</p>
<h2>Your choices</h2><p>When the cookie banner is enabled, you can choose Accept all or Necessary only. Your selection is stored in the browser and, for signed-in users, may also be recorded on the account. If DRIGHT publishes a materially new consent version, the banner can be shown again.</p>
<h2>Browser controls</h2><p>You can also clear or block browser cookies/storage using browser settings, but blocking necessary storage can prevent sign-in or other core functions from working correctly.</p>
<h2>Changes</h2><p>DRIGHT can update this Cookie Policy when technologies, service providers or legal requirements change.</p>
<p><em>This policy is a product-policy draft and should be reviewed by qualified counsel for the countries in which DRIGHT operates.</em></p>',true,now(),1,false)
on conflict(slug) do update set
  title=excluded.title,page_type='cookie',content=excluded.content,is_published=true,is_deleted=false,updated_at=now();

